<?php
declare(strict_types=1);
session_start();
require __DIR__.'/bootstrap.php';
$pdo=cc_db();
function ae($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function csrf():string{if(empty($_SESSION['cc_csrf']))$_SESSION['cc_csrf']=bin2hex(random_bytes(16));return $_SESSION['cc_csrf'];}
function require_csrf():void{if(!hash_equals($_SESSION['cc_csrf']??'',$_POST['csrf']??'')){http_response_code(403);exit('Invalid request');}}
$msg='';$err='';
if(isset($_GET['logout'])){session_destroy();header('Location: /admin.php');exit;}
if(!$pdo){$err='Database configuration is not available yet.';}
if($pdo && isset($_GET['token'])){
  $hash=hash('sha256',(string)$_GET['token']);
  $st=$pdo->prepare("SELECT id FROM admin_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() LIMIT 1");$st->execute([$hash]);$id=$st->fetchColumn();
  if($id){$pdo->prepare('UPDATE admin_tokens SET used_at=NOW() WHERE id=?')->execute([$id]);$_SESSION['cc_admin']=true;session_regenerate_id(true);header('Location: /admin.php');exit;}else{$err='That admin link is invalid or expired.';}
}
if($pdo && empty($_SESSION['cc_admin']) && $_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='send_link'){
  $token=bin2hex(random_bytes(24));$hash=hash('sha256',$token);$pdo->prepare("DELETE FROM admin_tokens WHERE expires_at<NOW() OR used_at IS NOT NULL")->execute();$st=$pdo->prepare("INSERT INTO admin_tokens(token_hash,expires_at) VALUES(?,DATE_ADD(NOW(),INTERVAL 15 MINUTE))");$st->execute([$hash]);
  $scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$link=$scheme.'://'.($_SERVER['HTTP_HOST']??'beta.costacams.com').'/admin.php?token='.$token;
  if(cc_send_mail('[CostaCams] Secure admin sign-in',"A secure CostaCams admin sign-in was requested.\n\nThis link expires in 15 minutes and can be used once:\n{$link}\n\nIf you did not request it, ignore this email."))$msg='A secure sign-in link was sent to the private administrator email.';else{$err='Could not send the sign-in email.';}
}
$logged=!empty($_SESSION['cc_admin']);
if($pdo && $logged && $_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')!=='send_link'){
  require_csrf();$action=$_POST['action']??'';
  try{
    if($action==='save_stream'){
      $id=(int)($_POST['id']??0);$locationId=(int)($_POST['location_id']??0);$name=substr(trim($_POST['name']??''),0,160);$type=$_POST['stream_type']??'none';$allowed=['hls','iframe','external','none'];if(!in_array($type,$allowed,true))$type='none';$url=trim($_POST['stream_url']??'');$source=substr(trim($_POST['source_name']??''),0,120);$sourceUrl=trim($_POST['source_url']??'');$note=substr(trim($_POST['camera_note']??''),0,255);$active=!empty($_POST['active'])?1:0;
      if(!$locationId||!$name)throw new RuntimeException('Location and stream name are required.');
      if($id){$st=$pdo->prepare('UPDATE streams SET location_id=?,name=?,stream_type=?,stream_url=?,source_name=?,source_url=?,camera_note=?,active=? WHERE id=?');$st->execute([$locationId,$name,$type,$url?:null,$source?:null,$sourceUrl?:null,$note?:null,$active,$id]);$msg='Stream updated.';}else{$st=$pdo->prepare('INSERT INTO streams(location_id,name,stream_type,stream_url,source_name,source_url,camera_note,active,priority) VALUES(?,?,?,?,?,?,?,?,100)');$st->execute([$locationId,$name,$type,$url?:null,$source?:null,$sourceUrl?:null,$note?:null,$active]);$msg='Stream added.';}
    }elseif($action==='save_location'){
      $id=(int)($_POST['id']??0);$slug=preg_replace('/[^a-z0-9-]/','',strtolower($_POST['slug']??''));$name=substr(trim($_POST['name']??''),0,160);$region=substr(trim($_POST['region']??''),0,100);$lat=(float)($_POST['lat']??0);$lon=(float)($_POST['lon']??0);$featured=!empty($_POST['featured'])?1:0;$active=!empty($_POST['active'])?1:0;
      if(!$slug||!$name||!$region)throw new RuntimeException('Slug, name and region are required.');
      if($id){$st=$pdo->prepare('UPDATE locations SET slug=?,name=?,region=?,lat=?,lon=?,featured=?,active=? WHERE id=?');$st->execute([$slug,$name,$region,$lat,$lon,$featured,$active,$id]);$msg='Location updated.';}else{$st=$pdo->prepare("INSERT INTO locations(slug,name,region,lat,lon,timezone,active,featured) VALUES(?,?,?,?,?,'Australia/Brisbane',?,?)");$st->execute([$slug,$name,$region,$lat,$lon,$active,$featured]);$msg='Location added.';}
    }elseif($action==='resolve_report'){$id=(int)($_POST['id']??0);$pdo->prepare("UPDATE stream_reports SET status='resolved',resolved_at=NOW() WHERE id=?")->execute([$id]);$msg='Report resolved.';
    }elseif($action==='save_story'){$id=(int)($_POST['id']??0);$cat=in_array($_POST['category']??'news',['news','event'],true)?$_POST['category']:'news';$slug=preg_replace('/[^a-z0-9-]/','',strtolower($_POST['slug']??''));$title=substr(trim($_POST['title']??''),0,220);$summary=trim($_POST['summary']??'');$body=trim($_POST['body']??'');$source=substr(trim($_POST['source_name']??''),0,150);$sourceUrl=trim($_POST['source_url']??'');$eventDate=trim($_POST['event_date']??'');if(!$slug||!$title||!$summary||!$body)throw new RuntimeException('Story fields are incomplete.');if($id){$st=$pdo->prepare('UPDATE news_items SET category=?,slug=?,title=?,summary=?,body=?,source_name=?,source_url=?,event_date=?,active=1 WHERE id=?');$st->execute([$cat,$slug,$title,$summary,$body,$source?:null,$sourceUrl?:null,$eventDate?:null,$id]);$msg='Story updated.';}else{$st=$pdo->prepare('INSERT INTO news_items(category,slug,title,summary,body,source_name,source_url,event_date,published_at,active) VALUES(?,?,?,?,?,?,?,?,NOW(),1)');$st->execute([$cat,$slug,$title,$summary,$body,$source?:null,$sourceUrl?:null,$eventDate?:null]);$msg='Story added.';}
    }
  }catch(Throwable $e){$err=$e->getMessage();}
}
$locations=$pdo&&$logged?$pdo->query('SELECT * FROM locations ORDER BY sort_order,name')->fetchAll():[];
$streams=$pdo&&$logged?$pdo->query('SELECT s.*,l.name location_name FROM streams s JOIN locations l ON l.id=s.location_id ORDER BY l.sort_order,s.priority,s.id')->fetchAll():[];
$reports=$pdo&&$logged?$pdo->query("SELECT r.*,l.name location_name,s.name stream_name FROM stream_reports r LEFT JOIN locations l ON l.id=r.location_id LEFT JOIN streams s ON s.id=r.stream_id WHERE r.status='open' ORDER BY r.created_at DESC LIMIT 100")->fetchAll():[];
$stories=$pdo&&$logged?$pdo->query('SELECT * FROM news_items ORDER BY COALESCE(event_date,published_at) DESC,id DESC LIMIT 100')->fetchAll():[];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>CostaCams Administration</title><style>*{box-sizing:border-box}body{background:#050505;color:#f5f7f8;font:14px system-ui;margin:0}a{color:#58dcff}.w{max-width:1250px;margin:4vh auto;padding:20px}.box{background:#0d1011;border:1px solid #292e30;border-radius:15px;padding:18px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}input,select,textarea,button{width:100%;padding:9px;margin:4px 0 8px;background:#070909;color:white;border:1px solid #343a3d;border-radius:8px}textarea{min-height:80px}button{cursor:pointer;border-color:#50dcff}.row{display:flex;gap:8px}.row>*{flex:1}.ok{color:#75e4a6}.err{color:#ff9292}.muted{color:#99a5aa}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #262b2d;padding:8px;text-align:left;vertical-align:top}summary{cursor:pointer;font-weight:700}.small{font-size:12px}.top{display:flex;justify-content:space-between;gap:15px;align-items:center}</style></head><body><main class="w"><div class="top"><div><h1>CostaCams Administration</h1><a href="/">← Back to CostaCams</a></div><?php if($logged):?><a href="?logout=1">Sign out</a><?php endif;?></div><?php if($msg):?><p class="ok"><?=ae($msg)?></p><?php endif;?><?php if($err):?><p class="err"><?=ae($err)?></p><?php endif;?>
<?php if(!$logged):?><div class="box"><h2>Secure sign-in</h2><p class="muted">No administrator email address or password is exposed publicly. Request a one-time link sent to the private administrator mailbox.</p><form method="post"><input type="hidden" name="action" value="send_link"><button>Send me a secure admin link</button></form></div>
<?php else:?><input type="hidden" id="csrf" value="<?=ae(csrf())?>"><div class="box" style="background:#0d2028"><h2>📊 Website analytics</h2><p class="muted">Live viewers, page traffic, most visited cameras, Surf Match activity and direct access to Google Analytics.</p><a href="/analytics-dashboard.php" style="display:inline-block;border:1px solid #50dcff;border-radius:10px;padding:12px 16px;text-decoration:none;font-weight:800">Open private analytics dashboard →</a></div>
<div class="box"><h2>Open camera reports (<?=count($reports)?>)</h2><?php if(!$reports):?><p class="muted">No open reports.</p><?php else:?><table><tr><th>When</th><th>Camera</th><th>Issue</th><th>Details</th><th></th></tr><?php foreach($reports as $r):?><tr><td><?=ae($r['created_at'])?></td><td><?=ae($r['location_name']??'Unknown')?><?=!empty($r['stream_name'])?'<br><span class="small muted">'.ae($r['stream_name']).'</span>':''?></td><td><?=ae($r['issue'])?></td><td><?=ae($r['details'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=ae(csrf())?>"><input type="hidden" name="action" value="resolve_report"><input type="hidden" name="id" value="<?=ae($r['id'])?>"><button>Resolve</button></form></td></tr><?php endforeach;?></table><?php endif;?></div>
<div class="grid"><div class="box"><h2>Add location</h2><form method="post"><input type="hidden" name="csrf" value="<?=ae(csrf())?>"><input type="hidden" name="action" value="save_location"><input name="name" placeholder="Beach name" required><input name="slug" placeholder="url-slug" required><input name="region" placeholder="Region" required><div class="row"><input name="lat" type="number" step="0.000001" placeholder="Latitude" required><input name="lon" type="number" step="0.000001" placeholder="Longitude" required></div><label><input style="width:auto" type="checkbox" name="featured" value="1"> Featured</label> <label><input style="width:auto" type="checkbox" name="active" value="1" checked> Active</label><button>Add location</button></form></div>
<div class="box"><h2>Add stream</h2><form method="post"><input type="hidden" name="csrf" value="<?=ae(csrf())?>"><input type="hidden" name="action" value="save_stream"><select name="location_id" required><?php foreach($locations as $l):?><option value="<?=ae($l['id'])?>"><?=ae($l['name'])?></option><?php endforeach;?></select><input name="name" placeholder="Stream name" required><select name="stream_type"><option value="hls">HLS (.m3u8)</option><option value="iframe">Iframe / embed</option><option value="external">External source</option><option value="none">Forecast only</option></select><input name="stream_url" placeholder="Stream/embed URL"><input name="source_name" placeholder="Source name"><input name="source_url" placeholder="Original source URL"><textarea name="camera_note" placeholder="Note shown under player"></textarea><label><input style="width:auto" type="checkbox" name="active" value="1" checked> Active</label><button>Add stream</button></form></div></div>
<div class="box"><h2>Existing streams</h2><?php foreach($streams as $s):?><details><summary><?=ae($s['location_name'])?> — <?=ae($s['name'])?> <span class="muted">(<?=ae($s['stream_type'])?>)</span></summary><form method="post"><input type="hidden" name="csrf" value="<?=ae(csrf())?>"><input type="hidden" name="action" value="save_stream"><input type="hidden" name="id" value="<?=ae($s['id'])?>"><select name="location_id"><?php foreach($locations as $l):?><option value="<?=ae($l['id'])?>" <?=$l['id']==$s['location_id']?'selected':''?>><?=ae($l['name'])?></option><?php endforeach;?></select><input name="name" value="<?=ae($s['name'])?>"><select name="stream_type"><?php foreach(['hls','iframe','external','none'] as $t):?><option value="<?=$t?>" <?=$t===$s['stream_type']?'selected':''?>><?=$t?></option><?php endforeach;?></select><input name="stream_url" value="<?=ae($s['stream_url'])?>"><input name="source_name" value="<?=ae($s['source_name'])?>"><input name="source_url" value="<?=ae($s['source_url'])?>"><textarea name="camera_note"><?=ae($s['camera_note'])?></textarea><label><input style="width:auto" type="checkbox" name="active" value="1" <?=$s['active']?'checked':''?>> Active</label><button>Save stream</button></form></details><?php endforeach;?></div>
<div class="box"><h2>Add surf news / event</h2><form method="post"><input type="hidden" name="csrf" value="<?=ae(csrf())?>"><input type="hidden" name="action" value="save_story"><div class="row"><select name="category"><option value="news">News</option><option value="event">Event</option></select><input name="slug" placeholder="story-slug" required></div><input name="title" placeholder="Title" required><textarea name="summary" placeholder="Short summary" required></textarea><textarea name="body" placeholder="Full CostaCams article/summary shown on-site" required></textarea><div class="row"><input name="source_name" placeholder="Source"><input name="source_url" placeholder="Source URL"></div><input name="event_date" type="datetime-local"><button>Publish</button></form></div>
<div class="box"><h2>Published stories</h2><?php foreach($stories as $s):?><details><summary><?=ae(strtoupper($s['category']))?> — <?=ae($s['title'])?></summary><form method="post"><input type="hidden" name="csrf" value="<?=ae(csrf())?>"><input type="hidden" name="action" value="save_story"><input type="hidden" name="id" value="<?=ae($s['id'])?>"><div class="row"><select name="category"><option value="news" <?=$s['category']==='news'?'selected':''?>>News</option><option value="event" <?=$s['category']==='event'?'selected':''?>>Event</option></select><input name="slug" value="<?=ae($s['slug'])?>"></div><input name="title" value="<?=ae($s['title'])?>"><textarea name="summary"><?=ae($s['summary'])?></textarea><textarea name="body"><?=ae($s['body'])?></textarea><div class="row"><input name="source_name" value="<?=ae($s['source_name'])?>"><input name="source_url" value="<?=ae($s['source_url'])?>"></div><input name="event_date" type="datetime-local" value="<?=!empty($s['event_date'])?ae(date('Y-m-d\TH:i',strtotime($s['event_date']))):''?>"><button>Save story</button></form></details><?php endforeach;?></div>
<?php endif;?></main></body></html>